EMA 200 기울기 계산 개선:
// 더 안정적인 기울기 계산 (20봉 사용)
const lookback = Math.min(20, i);
const ema200Slope = lookback > 0 ? 
  (ema200Values[i] - ema200Values[i-lookback]) / ema200Values[i-lookback] : 0;
const trendUp = ema200Slope > 0.0001; // 0.01% 이상 상승

